import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:dusrelpdf/dusrelpdf.dart';
import 'package:test/test.dart';

// Fixtures are real PDFs generated by the repo's own CLI:
//   cargo run -p dusrelpdf-cli -- mock --pages 3 -o test/testdata/three.pdf
//   cargo run -p dusrelpdf-cli -- mock --pages 5 -o test/testdata/five.pdf
// Every test goes through the real cdylib (dart:ffi) and the real Rust
// core. Run with `dart test` from this package directory — the library
// path resolves against the repo layout automatically.
//
// NOTE: the flutter CLI is not installed on this machine, so no
// widget-level testing was run; only dart:ffi loading + operations
// are tested here.

Uint8List fixture(String name) => File('test/testdata/$name').readAsBytesSync();

/// A 1x1 transparent PNG (standard minimal fixture), for the
/// images-to-PDF / watermark / signature tests.
final Uint8List onePxPng = base64Decode(
  'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==',
);

int pageCount(Dusrelpdf pdf, Uint8List bytes) =>
    pdf.getPdfInfo(bytes).pageCount;

void main() {
  late Dusrelpdf pdf;

  setUpAll(() {
    pdf = Dusrelpdf();
  });

  test('version', () {
    expect(pdf.version, '0.1.0');
  });

  test('merge two PDFs', () {
    final a = fixture('three.pdf');
    final b = fixture('five.pdf');
    final out = pdf.merge([a, b]);
    expect(out.sublist(0, 5), utf8.encode('%PDF-'));
    expect(pageCount(pdf, out), 8);

    // Partial options: disabling bookmarks must still merge fine.
    final out2 = pdf.merge([a], options: {'add_bookmarks': false});
    expect(pageCount(pdf, out2), 3);
  });

  test('merge empty input is EMPTY_INPUT', () {
    expect(
      () => pdf.merge([]),
      throwsA(isA<DusrelException>()
          .having((e) => e.code, 'code', 'EMPTY_INPUT')
          .having((e) => e.messageHi, 'messageHi', isNotEmpty)),
    );
  });

  test('split returns one PDF per range', () {
    final outs = pdf.split(fixture('five.pdf'), [
      [1, 2],
      [3, 4, 5],
    ]);
    expect(outs, hasLength(2));
    expect(pageCount(pdf, outs[0]), 2);
    expect(pageCount(pdf, outs[1]), 3);
  });

  test('splitRanges from a range string', () {
    final outs = pdf.splitRanges(fixture('five.pdf'), '1-2,3-5');
    expect(outs, hasLength(2));
    expect(pageCount(pdf, outs[0]), 2);
    expect(pageCount(pdf, outs[1]), 3);
  });

  test('splitEachPage', () {
    final outs = pdf.splitEachPage(fixture('three.pdf'));
    expect(outs, hasLength(3));
    for (final out in outs) {
      expect(pageCount(pdf, out), 1);
    }
  });

  test('extractPages and extractPagesRange', () {
    final out = pdf.extractPages(fixture('five.pdf'), [2, 4]);
    expect(pageCount(pdf, out), 2);

    final out2 = pdf.extractPagesRange(fixture('five.pdf'), '1-3,5');
    expect(pageCount(pdf, out2), 4);
  });

  test('extractPagesRange("9") is INVALID_RANGE', () {
    expect(
      () => pdf.extractPagesRange(fixture('three.pdf'), '9'),
      throwsA(isA<DusrelException>()
          .having((e) => e.code, 'code', 'INVALID_RANGE')),
    );
  });

  test('extractPages([9]) is PAGE_OUT_OF_RANGE', () {
    expect(
      () => pdf.extractPages(fixture('three.pdf'), [9]),
      throwsA(isA<DusrelException>()
          .having((e) => e.code, 'code', 'PAGE_OUT_OF_RANGE')),
    );
  });

  test('removePages and reorderPages', () {
    final five = fixture('five.pdf');
    final removed = pdf.removePages(five, [2]);
    expect(pageCount(pdf, removed), 4);

    final reordered = pdf.reorderPages(five, [5, 4, 3, 2, 1]);
    expect(pageCount(pdf, reordered), 5);

    // Bad permutation: page listed twice.
    expect(
      () => pdf.reorderPages(five, [1, 1, 2, 3, 4]),
      throwsA(isA<DusrelException>()),
    );
  });

  test('rotate by 180 and reject 45', () {
    final out = pdf.rotate(fixture('three.pdf'), options: {'angle': 180});
    expect(pageCount(pdf, out), 3);
    expect(
        utf8.decode(out, allowMalformed: true).contains('/Rotate 180'), isTrue);

    expect(
      () => pdf.rotate(fixture('three.pdf'), options: {'angle': 45}),
      throwsA(isA<DusrelException>()
          .having((e) => e.code, 'code', 'INVALID_ANGLE')),
    );
  });

  test('getPdfInfo', () {
    final info = pdf.getPdfInfo(fixture('three.pdf'));
    expect(info.pageCount, 3);
    expect(info.version, '1.7');
    expect(info.encrypted, isFalse);
    expect(info.pageSizes, hasLength(3));
    expect(info.pageSizes[0], [595.0, 842.0]);

    expect(
      () => pdf.getPdfInfo(Uint8List.fromList(utf8.encode('not a pdf'))),
      throwsA(
          isA<DusrelException>().having((e) => e.code, 'code', 'INVALID_PDF')),
    );
  });

  test('imagesToPdf', () {
    final out = pdf.imagesToPdf([onePxPng, onePxPng]);
    expect(pageCount(pdf, out), 2);
  });

  test('addWatermark text and image', () {
    final three = fixture('three.pdf');
    final text = pdf.addWatermark(three, options: {
      'text': 'CONFIDENTIAL',
      'opacity': 0.5,
      'rotation': 0.0,
    });
    expect(pageCount(pdf, text), 3);

    final image = pdf.addWatermark(three, image: onePxPng);
    expect(pageCount(pdf, image), 3);

    expect(
      () => pdf.addWatermark(three, options: {'text': 'X', 'opacity': 2.0}),
      throwsA(isA<DusrelException>()),
    );
  });

  test('addPageNumbers', () {
    final out = pdf.addPageNumbers(fixture('three.pdf'),
        options: {'format': 'Page {n} of {total}'});
    expect(pageCount(pdf, out), 3);
  });

  test('placeSignature', () {
    final out = pdf.placeSignature(fixture('three.pdf'), onePxPng);
    expect(pageCount(pdf, out), 3);

    expect(
      () => pdf.placeSignature(fixture('three.pdf'), Uint8List(0)),
      throwsA(isA<DusrelException>()),
    );
  });

  test('bulkExtract keeps per-item errors', () {
    final items = pdf.bulkExtract(fixture('three.pdf'), [
      [1],
      [2, 3],
      [9],
    ]);
    expect(items, hasLength(3));
    expect(items[0].pdf, isNotNull);
    expect(pageCount(pdf, items[0].pdf!), 1);
    expect(items[1].pdf, isNotNull);
    expect(pageCount(pdf, items[1].pdf!), 2);
    expect(items[2].pdf, isNull);
    expect(items[2].errorCode, 'PAGE_OUT_OF_RANGE');
    // One bad selection must not fail the whole batch (no throw).
  });
}
